import 'package:flutter/material.dart';import '../../services/api_service.dart';
class AiStylistScreen extends StatefulWidget{const AiStylistScreen({super.key});@override State<AiStylistScreen> createState()=>_S();}class _S extends State<AiStylistScreen>{final q=TextEditingController(),api=ApiService();final msgs=<Map<String,dynamic>>[];bool busy=false;Future<void> send()async{final text=q.text.trim();if(text.isEmpty||busy)return;q.clear();setState((){msgs.add({'me':true,'text':text});busy=true;});try{final d=await api.stylist(text);setState(()=>msgs.add({'me':false,'text':'${d['reply']??''}','items':d['items']??[]}));}catch(e){setState(()=>msgs.add({'me':false,'text':'$e'}));}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('AI Stylist')),body:Column(children:[Expanded(child:msgs.isEmpty?const Center(child:Padding(padding:EdgeInsets.all(30),child:Text('Ask: “Create a casual outfit using my saved clothes.”',textAlign:TextAlign.center))):ListView.builder(padding:const EdgeInsets.all(16),itemCount:msgs.length,itemBuilder:(_,i){final m=msgs[i],me=m['me']==true;final items=(m['items'] as List?)??[];return Align(alignment:me?Alignment.centerRight:Alignment.centerLeft,child:Container(margin:const EdgeInsets.only(bottom:12),padding:const EdgeInsets.all(14),constraints:const BoxConstraints(maxWidth:520),decoration:BoxDecoration(color:me?Colors.black:Colors.white,borderRadius:BorderRadius.circular(18)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${m['text']}',style:TextStyle(color:me?Colors.white:Colors.black)),if(items.isNotEmpty)...[const SizedBox(height:10),SizedBox(height:120,child:ListView.separated(scrollDirection:Axis.horizontal,itemCount:items.length,separatorBuilder:(_,__)=>const SizedBox(width:8),itemBuilder:(_,j){final x=items[j] as Map;final u=x['image_url']?.toString();return SizedBox(width:90,child:Column(children:[Expanded(child:u!=null?Image.network(u,fit:BoxFit.cover):const Icon(Icons.checkroom)),Text('${x['name']??''}',maxLines:1,overflow:TextOverflow.ellipsis)]));}))]])));})),SafeArea(child:Padding(padding:const EdgeInsets.all(12),child:Row(children:[Expanded(child:TextField(controller:q,onSubmitted:(_)=>send(),decoration:const InputDecoration(hintText:'Ask your stylist...'))),IconButton(onPressed:busy?null:send,icon:busy?const SizedBox(width:20,height:20,child:CircularProgressIndicator()):const Icon(Icons.send_rounded))]))) ]));}
